    deltaData,
    referenceTraceId,
    stagedLaps
}) => {
    const [isExpanded, setIsExpanded] = useState(false);
    const [hiddenIndices, setHiddenIndices] = useState<Set<number>>(new Set());

    const { series, chartColors, allColors, refLapInfo } = useMemo(() => {
        const activeSeries: any[] = [];
        const activeColors: string[] = [];

        const baseColors = generateSeriesColors(stagedLaps.map(s => ({ team_name: s.driver.team_name })));

        // Find reference lap info for display
        const refLap = stagedLaps.find(sl => `${sl.driver.name_acronym}_L${sl.lap.lap_number}` === referenceTraceId);
        const refInfoStr = refLap ? `${refLap.driver.name_acronym} L${refLap.lap.lap_number}` : 'REF';

        stagedLaps.forEach((sl, index) => {
            const traceId = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;

            // Skip rendering the reference line (it's always 0)
            if (traceId === referenceTraceId) return;
            if (hiddenIndices.has(index)) return;

            const key = `delta_${traceId}`;
            const seriesData = deltaData.map(p => [p.distance, p[key] || 0]);

            activeSeries.push({
                name: `${sl.driver.name_acronym} (L${sl.lap.lap_number})`,
                data: seriesData
            });
            activeColors.push(baseColors[index]);
        });

        return { 
            series: activeSeries, 
            chartColors: activeColors, 
            allColors: baseColors,
            refLapInfo: refInfoStr
        };
    }, [deltaData, stagedLaps, hiddenIndices, referenceTraceId]);

    const toggleVisibility = (index: number) => {
        const next = new Set(hiddenIndices);
        if (next.has(index)) next.delete(index);
        else next.add(index);
        setHiddenIndices(next);
    };

    const options: ApexOptions = useMemo(() => ({
        chart: {
            type: 'line',
            animations: { enabled: false },
            background: 'transparent',
            toolbar: { show: isExpanded },
            zoom: { enabled: isExpanded, type: 'x', autoScaleYaxis: true },
            parentHeightOffset: 0,
        },
        theme: { mode: 'dark' },
        colors: chartColors,
        stroke: {
            curve: 'smooth',
            width: 2
        },
        fill: {
            type: 'gradient',
            gradient: {
                shade: 'dark',
                type: 'vertical',
                shadeIntensity: 0.5,
                inverseColors: false,
                opacityFrom: 0.5,
                opacityTo: 0.1,
                stops: [0, 100]
            }
        },
        grid: {
            borderColor: '#334155',
            strokeDashArray: 3,
            xaxis: { lines: { show: false } },
            yaxis: { lines: { show: true } },
            padding: { top: 10, right: 10, bottom: 0, left: 10 }
        },
        xaxis: {
            type: 'numeric',
            tooltip: { enabled: isExpanded },
            axisBorder: { show: false },
            axisTicks: { show: false },
            labels: {
                style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
                formatter: (val: string) => `${Math.round(Number(val))}m`
            }
        },
        yaxis: {
            title: { 
                text: 'Delta (s)',
                style: { color: '#94a3b8', fontSize: '10px', fontFamily: 'Inter, sans-serif' }
            },
            labels: {
                style: { colors: '#94a3b8', fontSize: '11px', fontFamily: 'JetBrains Mono, monospace' },
                formatter: (val) => {
                    const num = Number(val);
                    return num > 0 ? `+${num.toFixed(2)}` : num.toFixed(2);
                }
            },
        },
        markers: { size: 0 },
        legend: { show: false },
        tooltip: {
            theme: 'dark',
            shared: true,
            intersect: false,
            style: { fontSize: '12px', fontFamily: 'JetBrains Mono, monospace' },
            x: { formatter: (val) => `${Math.round(Number(val))}m` },
            y: {
                formatter: (val) => {
                    const num = Number(val);
                    return `${num >= 0 ? '+' : ''}${num.toFixed(3)}s`;
                }
            }
        },
        annotations: {
            yaxis: [{
                y: 0,
                borderColor: '#ffffff',
                strokeDashArray: 2,
                opacity: 0.3,
                label: {
                    borderColor: 'transparent',
                    style: { color: '#fff', background: 'transparent', fontSize: '10px' },
                    text: 'REF'
                }
            }]
        }
    }), [chartColors, isExpanded]);

    if (!deltaData || deltaData.length === 0) return null;

    return (
        <>
